CREATE TABLE "alert_rules" ("id" TEXT NOT NULL, "series_id" TEXT NOT NULL REFERENCES schedule_series (id) ON DELETE CASCADE, "scope_key" TEXT NOT NULL DEFAULT '*', "kind" TEXT NOT NULL, "enabled" INTEGER NOT NULL CHECK ("enabled" IN (0, 1)), "offset_minutes" INTEGER NOT NULL, "date_only_anchor_time" TEXT NULL, "date_only_anchor_zone" TEXT NULL, "lock_screen_details" TEXT NOT NULL, "presentation_preference" TEXT NOT NULL, "snooze_minutes" INTEGER NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"), UNIQUE ("series_id", "scope_key", "kind"));
CREATE TABLE "appearance_preferences" ("id" INTEGER NOT NULL, "theme_mode" TEXT NOT NULL DEFAULT 'system', "accent_key" TEXT NOT NULL DEFAULT 'blue', "density" TEXT NOT NULL DEFAULT 'comfortable', "show_category_colors" INTEGER NOT NULL DEFAULT 1 CHECK ("show_category_colors" IN (0, 1)), "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "categories" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "color_key" TEXT NULL, "built_in" INTEGER NOT NULL DEFAULT 0 CHECK ("built_in" IN (0, 1)), "sort_order" INTEGER NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "import_commits" ("command_id" TEXT NOT NULL, "payload_hash" TEXT NOT NULL, "series_ids_json" TEXT NOT NULL, "committed_at" INTEGER NOT NULL, PRIMARY KEY ("command_id"));
CREATE TABLE "import_drafts" ("id" TEXT NOT NULL, "source_type" TEXT NOT NULL, "source_ref" TEXT NULL, "source_revision" INTEGER NOT NULL, "draft_revision" INTEGER NOT NULL, "payload_json" TEXT NOT NULL, "review_state" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "expires_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "import_provenance" ("id" TEXT NOT NULL, "series_id" TEXT NOT NULL REFERENCES schedule_series (id) ON DELETE CASCADE, "source_type" TEXT NOT NULL, "share_id" TEXT NULL, "source_item_id" TEXT NULL, "source_revision" INTEGER NULL, "image_draft_id" TEXT NULL, "fingerprint" TEXT NOT NULL, "imported_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "key_values" ("key" TEXT NOT NULL, "value" TEXT NOT NULL, PRIMARY KEY ("key"));
CREATE TABLE "occurrence_exceptions" ("id" TEXT NOT NULL, "series_id" TEXT NOT NULL REFERENCES schedule_series (id) ON DELETE CASCADE, "original_key" TEXT NOT NULL, "action" TEXT NOT NULL, "replacement_json" TEXT NULL, "revision" INTEGER NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"), UNIQUE ("series_id", "original_key"));
CREATE TABLE "owned_share_links" ("share_id" TEXT NOT NULL, "snapshot_version" INTEGER NOT NULL, "item_count" INTEGER NOT NULL, "category_labels_json" TEXT NOT NULL, "route_path" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "expires_at" INTEGER NOT NULL, "revoked_at" INTEGER NULL, PRIMARY KEY ("share_id"));
CREATE TABLE "pending_share_creations" ("idempotency_key" TEXT NOT NULL, "payload_json" TEXT NOT NULL, "expires_at" INTEGER NOT NULL, "created_at" INTEGER NOT NULL, PRIMARY KEY ("idempotency_key"));
CREATE TABLE "reconciliation_outbox" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "operation_key" TEXT NOT NULL UNIQUE, "reason" TEXT NOT NULL, "source_revision" INTEGER NOT NULL, "status" TEXT NOT NULL, "attempts" INTEGER NOT NULL DEFAULT 0, "next_attempt_at" INTEGER NULL, "created_at" INTEGER NOT NULL);
CREATE TABLE "schedule_series" ("id" TEXT NOT NULL, "revision" INTEGER NOT NULL, "title" TEXT NOT NULL, "category_id" TEXT NULL REFERENCES categories (id) ON DELETE SET NULL, "time_kind" TEXT NOT NULL, "start_date" TEXT NOT NULL, "start_time" TEXT NULL, "time_zone" TEXT NULL, "end_time" TEXT NULL, "end_day_offset" INTEGER NULL, "seed_time_resolution" TEXT NULL, "end_time_resolution" TEXT NULL, "end_date_exclusive" TEXT NULL, "recurrence_frequency" TEXT NULL, "recurrence_weekdays" TEXT NULL, "recurrence_until" TEXT NULL, "location" TEXT NULL, "professor" TEXT NULL, "subtitle" TEXT NULL, "notes" TEXT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "scheduled_alerts" ("request_key" TEXT NOT NULL, "rule_id" TEXT NOT NULL, "series_id" TEXT NOT NULL, "occurrence_key" TEXT NOT NULL, "kind" TEXT NOT NULL, "platform" TEXT NOT NULL, "source_revision" INTEGER NOT NULL, "native_request_id" TEXT NULL, "trigger_at" INTEGER NOT NULL, "status" TEXT NOT NULL, "error_code" TEXT NULL, "last_reconciled_at" INTEGER NOT NULL, PRIMARY KEY ("request_key"));
CREATE TABLE "widget_configurations" ("widget_id" TEXT NOT NULL, "category_filter" TEXT NULL, "layout" TEXT NOT NULL DEFAULT 'expanded', "surface" TEXT NOT NULL DEFAULT 'clear', "text_tone" TEXT NOT NULL DEFAULT 'light', "next_emphasis" INTEGER NOT NULL DEFAULT 1 CHECK ("next_emphasis" IN (0, 1)), "show_location" INTEGER NOT NULL DEFAULT 1 CHECK ("show_location" IN (0, 1)), "show_professor" INTEGER NOT NULL DEFAULT 1 CHECK ("show_professor" IN (0, 1)), "show_subtitle" INTEGER NOT NULL DEFAULT 1 CHECK ("show_subtitle" IN (0, 1)), "match_app" INTEGER NOT NULL DEFAULT 0 CHECK ("match_app" IN (0, 1)), "revision" INTEGER NOT NULL DEFAULT 0, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("widget_id"));
